function showToast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2300)}
function openModal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal">${html}</div></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});$$('.modal-close').forEach(b=>b.onclick=closeModal)}
function closeModal(){$('#modal-root').innerHTML=''}
function showTutorial(){openModal(`<button class="modal-close">×</button><div class="eyebrow">WELCOME TO RISING ELEVEN</div><h2>Every legend starts somewhere.</h2><p class="modal-sub">A quick field guide before your first big signing.</p><div class="tutorial-step"><div class="tutorial-num">01</div><div><strong>Build your club</strong><p>Scout original players across five rarities. Your free character select lets you choose the first star personally.</p></div></div><div class="tutorial-step"><div class="tutorial-num">02</div><div><strong>Set your starting eleven</strong><p>Arrange your best players in the 4—3—3 formation. Tap a spot, then pick a player from your team sheet.</p></div></div><div class="tutorial-step"><div class="tutorial-num">03</div><div><strong>Take it to the pitch</strong><p>Pass to build an attack, dribble to beat a marker, shoot when the moment is right, or defend to win the ball back.</p></div></div><div class="modal-actions"><button class="button-primary" data-action="tutorial-next">LET'S BUILD YOUR CLUB →</button></div>`)}
function showFreePick(){if(state.freePickUsed){showToast('Your free character select has already been used.');return}const picks=[];while(picks.length<3){const p=randomPlayer([2,3,4]);if(!picks.includes(p))picks.push(p)}openModal(`<button class="modal-close">×</button><div class="eyebrow">YOUR FIRST STAR · FREE SELECT</div><h2>Choose your player.</h2><p class="modal-sub">One free character select. Pick the player who feels right — they are yours to keep.</p><div class="pick-grid">${picks.map(p=>`<div class="pick-card rarity-${rarityClass[p.r]}" data-pick="${p.id}"><div class="card-art">${portrait(p)}<span class="card-overall">${p.overall}</span><span class="rarity-tag">${p.rarity}</span></div><div class="card-info"><strong>${p.name}</strong><small>${p.position} · ${p.team}</small></div></div>`).join('')}</div><p class="pick-warning">This choice is permanent. Tap a card to recruit.</p>`);$$('[data-pick]').forEach(el=>el.onclick=()=>chooseFreePick(Number(el.dataset.pick)))}
function chooseFreePick(id){const p=player(id);state.freePickUsed=true;recruit(id);if(!state.missionClaimed.includes(1)){state.tickets++;state.missionClaimed.push(1)}save();closeModal();showToast(`${p.name} joined your club!`);renderApp();}
function randomPlayer(allow=[0,1,2,3,4]){const r=Math.random();let rarity;if(allow.length===3&&allow.join(',')==='2,3,4'){rarity=r<.7?2:r<.95?3:4}else{rarity=r<.35?0:r<.65?1:r<.87?2:r<.97?3:4}if(!allow.includes(rarity))rarity=allow[Math.floor(Math.random()*allow.length)];const pool=players.filter(p=>p.r===rarity);return pool[Math.floor(Math.random()*pool.length)]}
function recruit(id){if(!state.owned.includes(id))state.owned.push(id);if(state.squad.length<11&&!state.squad.includes(id))state.squad.push(id)}
function pull(count=1,usingTicket=false){if(usingTicket){if(state.tickets<1){showToast('No free scout tickets available.');return}state.tickets--}else{const cost=count===10?1350:150;if(state.gems<cost){showToast('Not enough premium gems.');return}state.gems-=cost}const results=[];for(let i=0;i<count;i++){const p=randomPlayer();results.push(p);if(state.owned.includes(p.id))state.coins+=100;else recruit(p.id)}save();renderApp();const cards=results.map(p=>card(p)).join('');openModal(`<button class="modal-close">×</button><div class="result-banner"><div class="big-star">✦</div><div class="eyebrow">SCOUT RESULTS</div><h2>${count===1?'A new face joins the club.':'Ten new stories begin.'}</h2><p class="modal-sub">${results.filter(p=>!state.owned.slice(0,0).includes(p.id)).length} scouts complete · duplicates trade for 100 coins.</p></div><div class="pull-result">${cards}</div><div class="modal-actions"><button class="button-primary modal-done">BACK TO CLUB</button></div>`);$$('.modal-done').forEach(b=>b.onclick=closeModal)}
function showPlayerDetails(id){const p=player(id);const owned=state.owned.includes(id);openModal(`<button class="modal-close">×</button><div class="detail-card"><div class="detail-art">${portrait(p)}</div><div class="detail-copy"><div class="eyebrow">${p.team}</div><h2>${p.name}</h2><div class="detail-rating">${p.overall}<span style="font-size:11px;color:#8da2b6"> OVR</span></div><div class="detail-stat"><span>RARITY</span><b style="color:${['#a6bbc9','#64d5e7','#ba8fff','#ffae66','#f267af'][p.r]}">${p.rarity}</b></div><div class="detail-stat"><span>POSITION</span><b>${p.position}</b></div><div class="detail-stat"><span>SHIRT NO.</span><b>#${p.number}</b></div><div class="detail-stat"><span>CLUB STATUS</span><b>${owned?'RECRUITED':'SCOUT TARGET'}</b></div></div></div><p class="modal-sub" style="margin-top:15px">${p.special?'A generational talent with a once-in-a-lifetime spark.':'A determined talent with everything to prove. Their journey starts with your club.'}</p>${owned?`<div class="modal-actions"><button class="button-primary" data-action="detail-add" data-id="${id}">ADD TO STARTING XI</button></div>`:`<div class="modal-actions"><button class="button-ghost modal-done">CLOSE</button><button class="button-primary" data-tab="scout">FIND IN SCOUT →</button></div>`}`);$$('.modal-done').forEach(b=>b.onclick=closeModal)}

