function renderHeader(){const c=$('.coin-count'),g=$('.gem-count'),t=$('.ticket-count');if(c)c.textContent=formatNum(state.coins);if(g)g.textContent=formatNum(state.gems);if(t)t.textContent=state.tickets;}
